import React, { useState } from 'react';

export default function MyBorrowings() {
  // ข้อมูลจำลองรายการที่เคยขอยืม (จำลองสถานะเพื่อรอเชื่อม Backend ของเพื่อน)
  const [borrowList, setBorrowList] = useState([
    {
      id: 1,
      equipmentName: "Sony Mirrorless Camera Alpha 6400",
      quantity: 1,
      borrowDate: "2026-11-15",
      returnDate: "2026-11-18",
      purpose: "ถ่ายโปรเจกต์วิดีโอส่งอาจารย์",
      status: "รออนุมัติ" // รออนุมัติ, กำลังใช้งาน, คืนแล้ว, ยกเลิก
    },
    {
      id: 2,
      equipmentName: "Shure SM58 Vocal Microphone",
      quantity: 2,
      borrowDate: "2026-11-10",
      returnDate: "2026-11-12",
      purpose: "อัดเสียงพอดแคสต์กิจกรรมคณะ",
      status: "กำลังใช้งาน"
    }
  ]);

  const getStatusBadge = (status) => {
    switch (status) {
      case 'รออนุมัติ':
        return <span style={{ background: '#FEF3C7', color: '#D97706', padding: '4px 10px', borderRadius: '20px', fontSize: '12px', fontWeight: '600' }}>⏳ รออนุมัติ</span>;
      case 'กำลังใช้งาน':
        return <span style={{ background: '#DBEAFE', color: '#1D4ED8', padding: '4px 10px', borderRadius: '20px', fontSize: '12px', fontWeight: '600' }}>🔄 กำลังใช้งาน</span>;
      case 'คืนแล้ว':
        return <span style={{ background: '#DCFCE7', color: '#15803D', padding: '4px 10px', borderRadius: '20px', fontSize: '12px', fontWeight: '600' }}>✅ คืนแล้ว</span>;
      default:
        return <span style={{ background: '#F1F5F9', color: '#475569', padding: '4px 10px', borderRadius: '20px', fontSize: '12px', fontWeight: '600' }}>{status}</span>;
    }
  };

  return (
    <div style={{ maxWidth: '900px', margin: '30px auto', padding: '0 20px' }}>
      <h2 style={{ color: '#1E293B', marginBottom: '8px', fontSize: '22px' }}>📦 ประวัติการขอยืมอุปกรณ์ของฉัน</h2>
      <p style={{ color: '#64748B', marginBottom: '24px', fontSize: '14px' }}>ตรวจสอบสถานะคำขอยืมและกำหนดคืนอุปกรณ์ของคุณ</p>

      {borrowList.length === 0 ? (
        <div style={{ textAlign: 'center', padding: '40px', background: '#FFFFFF', borderRadius: '12px', border: '1px solid #E2E8F0', color: '#64748B' }}>
          ยังไม่มีประวัติการขอยืมอุปกรณ์
        </div>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
          {borrowList.map((item) => (
            <div key={item.id} style={{
              background: '#FFFFFF',
              padding: '20px',
              borderRadius: '12px',
              border: '1px solid #E2E8F0',
              boxShadow: '0 2px 10px rgba(0,0,0,0.02)',
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'center',
              flexWrap: 'wrap',
              gap: '16px'
            }}>
              <div style={{ flex: 1, minWidth: '250px' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '10px', marginBottom: '6px' }}>
                  <h4 style={{ margin: 0, color: '#1E293B', fontSize: '16px' }}>{item.equipmentName}</h4>
                  {getStatusBadge(item.status)}
                </div>
                <p style={{ margin: '0 0 4px 0', fontSize: '13px', color: '#475569' }}>
                  📌 <strong>จำนวนที่ยืม:</strong> {item.quantity} ชิ้น
                </p>
                <p style={{ margin: '0 0 4px 0', fontSize: '13px', color: '#475569' }}>
                  📅 <strong>วันที่ยืม - คืน:</strong> {item.borrowDate} ถึง {item.returnDate}
                </p>
                <p style={{ margin: 0, fontSize: '13px', color: '#64748B' }}>
                  💬 <strong>วัตถุประสงค์:</strong> {item.purpose}
                </p>
              </div>

              {item.status === 'รออนุมัติ' && (
                <button 
                  onClick={() => {
                    if(window.confirm('คุณต้องการยกเลิกคำขอนี้ใช่หรือไม่?')) {
                      setBorrowList(borrowList.filter(b => b.id !== item.id));
                    }
                  }}
                  style={{
                    padding: '8px 14px',
                    background: '#FEF2F2',
                    color: '#DC2626',
                    border: '1px solid #FCA5A5',
                    borderRadius: '6px',
                    fontSize: '13px',
                    fontWeight: '600',
                    cursor: 'pointer'
                  }}
                >
                  ยกเลิกคำขอ
                </button>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
